// Writes src/environments/environment.ts from the Supabase settings.
// Values are read from (lowest to highest priority): .env, .env.local, process.env.
// process.env is where Vercel and CI provide them. The generated file is not committed.
import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const outputFile = resolve(root, 'src/environments/environment.ts');

function readEnvFile(file) {
  if (!existsSync(file)) return {};
  const values = {};
  for (const rawLine of readFileSync(file, 'utf8').split(/\r?\n/)) {
    const line = rawLine.trim();
    if (!line || line.startsWith('#')) continue;
    const eq = line.indexOf('=');
    if (eq <= 0) continue;
    const key = line.slice(0, eq).trim();
    let value = line.slice(eq + 1).trim();
    if ((value.startsWith('"') && value.endsWith('"')) || (value.startsWith("'") && value.endsWith("'"))) {
      value = value.slice(1, -1);
    }
    values[key] = value;
  }
  return values;
}

const env = {
  ...readEnvFile(resolve(root, '.env')),
  ...readEnvFile(resolve(root, '.env.local')),
  ...process.env,
};

let supabaseUrl = (env.NG_APP_SUPABASE_URL ?? '').trim().replace(/\/+$/, '');
let anonKey = (env.NG_APP_SUPABASE_ANON_KEY ?? '').trim();

// `npm test` runs with placeholder values when none are set: the unit tests never call Supabase.
if ((!supabaseUrl || !anonKey) && env.npm_lifecycle_event === 'pretest') {
  supabaseUrl = 'https://test-project.supabase.co';
  anonKey = 'test-anon-key';
  console.log('Using placeholder Supabase settings for unit tests (no network calls are made).');
}

if (!supabaseUrl || !anonKey) {
  console.error(
    [
      'Missing Supabase settings for the Support Workspace.',
      'Copy support-workspace/.env.example to .env.local and set:',
      '  NG_APP_SUPABASE_URL=https://<your-project>.supabase.co',
      '  NG_APP_SUPABASE_ANON_KEY=<anon public key>',
    ].join('\n')
  );
  process.exit(1);
}

const source = `// Generated by scripts/generate-environment.mjs. Do not edit by hand.
// Change NG_APP_SUPABASE_URL and NG_APP_SUPABASE_ANON_KEY in .env.local instead.
export const environment = {
  production: ${env.NODE_ENV === 'production' ? 'true' : 'false'},
  supabaseUrl: ${JSON.stringify(supabaseUrl)},
  supabaseAnonKey: ${JSON.stringify(anonKey)},
  apiUrl: ${JSON.stringify(`${supabaseUrl}/rest/v1`)},
};
`;

mkdirSync(dirname(outputFile), { recursive: true });
writeFileSync(outputFile, source);
console.log(`Wrote ${outputFile.replace(root + '/', '')} for ${supabaseUrl}`);
